<?php

declare(strict_types=1);

namespace App\Filament\Actions;

use App\Shared\Helpers\AppHelper;
use CodeWithDennis\FilamentLucideIcons\Enums\LucideIcon;
use Filament\Actions\Action;
use Override;

/**
 * "Help" link rendered above a form field (as a hint action) that opens the matching
 * section of the user guide at docs.dalin.cz in a new tab.
 *
 * Usage: ->hintAction(HelpLinkAction::to('stranka-uzivatelska-nastaveni', 'komu-se-e-mail-pošle'))
 *
 * The anchor is the heading id generated by Zudoku — the heading text lowercased with spaces
 * replaced by dashes, diacritics kept (e.g. "Komu se e-mail pošle" → "komu-se-e-mail-pošle").
 */
final class HelpLinkAction extends Action
{
    #[Override]
    public static function getDefaultName(): string
    {
        return 'help';
    }

    /**
     * @param string $page help page slug under /napoveda/, without the .html suffix
     * @param string|null $anchor heading id on that page
     */
    public static function to(string $page, ?string $anchor = null): static
    {
        return self::make()->docs($page, $anchor);
    }

    #[Override]
    protected function setUp(): void
    {
        parent::setUp();

        $this->label(__('filament/common.help_link.label'))
            ->tooltip(__('filament/common.help_link.tooltip'))
            ->icon(LucideIcon::BookOpenText)
            ->color('primary')
            ->link()
            ->openUrlInNewTab();
    }

    public function docs(string $page, ?string $anchor = null): static
    {
        $url = AppHelper::getPageHelpUrl($page);

        if ($anchor !== null && $anchor !== '') {
            $url .= '#'.rawurlencode($anchor);
        }

        return $this->url($url);
    }
}
